package tool

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os/exec"
	"time"

	"github.com/emergingrobotics/erg/internal/agent"
)

const bashToolName = "bash"

const defaultBashTimeout = 120 * time.Second

// Bash runs a shell command and returns its combined output. It is the seam
// through which every external capability is reached. Output is capped and the
// command is bounded by a timeout.
type Bash struct{}

func (Bash) Name() string { return bashToolName }

func (Bash) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        bashToolName,
		Description: "Run a command with `sh -c` in the working directory and return its combined stdout/stderr and exit status.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "command": {"type": "string", "description": "The command line to run."},
    "timeout_seconds": {"type": "integer", "description": "Kill the command after this many seconds (default 120)."}
  },
  "required": ["command"]
}`),
	}
}

type bashArgs struct {
	Command        string  `json:"command"`
	TimeoutSeconds flexInt `json:"timeout_seconds"`
}

func (Bash) Run(ctx context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a bashArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Command == "" {
		return toolErr("command is required")
	}

	timeout := defaultBashTimeout
	if a.TimeoutSeconds > 0 {
		timeout = time.Duration(int(a.TimeoutSeconds)) * time.Second
	}
	if env.Limits.Timeout > 0 && env.Limits.Timeout < timeout {
		timeout = env.Limits.Timeout
	}

	runCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	cmd := exec.CommandContext(runCtx, "sh", "-c", a.Command)
	cmd.Dir = env.Cwd
	var buf bytes.Buffer
	cmd.Stdout = &buf
	cmd.Stderr = &buf

	err := cmd.Run()
	out := capBytes(buf.String(), defaultMaxOutputBytes)

	if errors.Is(runCtx.Err(), context.DeadlineExceeded) {
		return toolErr(fmt.Sprintf("command timed out after %s\n%s", timeout, out))
	}
	if err != nil {
		var exit *exec.ExitError
		if errors.As(err, &exit) {
			return toolErr(fmt.Sprintf("exit status %d\n%s", exit.ExitCode(), out))
		}
		return toolErr(fmt.Sprintf("%v\n%s", err, out))
	}
	if out == "" {
		out = "(no output)"
	}
	return ok(out)
}

package tool

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/emergingrobotics/erg/internal/agent"
)

const (
	readToolName  = "read"
	writeToolName = "write"
	editToolName  = "edit"
	globToolName  = "glob"
	listToolName  = "list"
)

// Read returns the contents of a file, optionally a line range. A directory
// path yields a listing of its entries so the model can navigate the tree.
type Read struct{}

func (Read) Name() string { return readToolName }

func (Read) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        readToolName,
		Description: "Read a UTF-8 text file, or list a directory's entries when the path is a directory. Optionally start at a 1-based line offset and limit the number of lines (files only).",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "File path, absolute or relative to the working directory."},
    "offset": {"type": "integer", "description": "1-based first line to return."},
    "limit": {"type": "integer", "description": "Maximum number of lines to return."}
  },
  "required": ["path"]
}`),
	}
}

type readArgs struct {
	Path   string  `json:"path"`
	Offset flexInt `json:"offset"`
	Limit  flexInt `json:"limit"`
}

func (Read) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a readArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Path == "" {
		return toolErr("path is required")
	}
	path := resolvePath(env, a.Path)
	info, err := os.Stat(path)
	if err != nil {
		return toolErr(err.Error())
	}
	if info.IsDir() {
		listing, err := listDir(path)
		if err != nil {
			return toolErr(err.Error())
		}
		return ok(capBytes(listing, defaultMaxOutputBytes))
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return toolErr(err.Error())
	}
	content := string(data)
	if a.Offset > 0 || a.Limit > 0 {
		content = sliceLines(content, int(a.Offset), int(a.Limit))
	}
	return ok(capBytes(content, defaultMaxOutputBytes))
}

// listDir renders a directory's entries, one per line, sorted, with a trailing
// slash marking subdirectories so the model can tell files from directories.
func listDir(path string) (string, error) {
	entries, err := os.ReadDir(path)
	if err != nil {
		return "", err
	}
	var b strings.Builder
	fmt.Fprintf(&b, "directory %s (%d entries):\n", path, len(entries))
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() {
			name += "/"
		}
		b.WriteString(name + "\n")
	}
	return b.String(), nil
}

func sliceLines(content string, offset, limit int) string {
	lines := strings.Split(content, "\n")
	start := 0
	if offset > 1 {
		start = offset - 1
	}
	if start > len(lines) {
		start = len(lines)
	}
	end := len(lines)
	if limit > 0 && start+limit < end {
		end = start + limit
	}
	return strings.Join(lines[start:end], "\n")
}

// Glob lists files matching a shell pattern, so the model can discover files by
// name without shelling out. Matches are returned relative to the working
// directory, sorted.
type Glob struct{}

func (Glob) Name() string { return globToolName }

func (Glob) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        globToolName,
		Description: "List files matching a glob pattern (e.g. \"src/*.c\", \"**/x*.go\"). Paths are relative to the working directory.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "pattern": {"type": "string", "description": "Glob pattern, absolute or relative to the working directory."}
  },
  "required": ["pattern"]
}`),
	}
}

type globArgs struct {
	Pattern string `json:"pattern"`
}

func (Glob) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a globArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Pattern == "" {
		return toolErr("pattern is required")
	}
	matches, err := filepath.Glob(resolvePath(env, a.Pattern))
	if err != nil {
		return toolErr(err.Error())
	}
	if len(matches) == 0 {
		return ok("no matches for " + a.Pattern)
	}
	sort.Strings(matches)
	for i, m := range matches {
		if rel, err := filepath.Rel(env.Cwd, m); err == nil && !strings.HasPrefix(rel, "..") {
			matches[i] = rel
		}
	}
	return ok(capBytes(strings.Join(matches, "\n"), defaultMaxOutputBytes))
}

// List returns a directory's entries. It is the same listing the read tool
// produces for a directory, offered under its own name so the model can list
// without shelling out.
type List struct{}

func (List) Name() string { return listToolName }

func (List) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        listToolName,
		Description: "List the entries of a directory. Subdirectories are marked with a trailing slash.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "Directory path, absolute or relative to the working directory. Defaults to the working directory."}
  }
}`),
	}
}

type listArgs struct {
	Path string `json:"path"`
}

func (List) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a listArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	path := resolvePath(env, a.Path)
	info, err := os.Stat(path)
	if err != nil {
		return toolErr(err.Error())
	}
	if !info.IsDir() {
		return toolErr(path + " is not a directory")
	}
	listing, err := listDir(path)
	if err != nil {
		return toolErr(err.Error())
	}
	return ok(capBytes(listing, defaultMaxOutputBytes))
}

// Write creates or overwrites a file, creating parent directories as needed.
type Write struct{}

func (Write) Name() string { return writeToolName }

func (Write) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        writeToolName,
		Description: "Create or overwrite a file with the given content. Parent directories are created.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "path": {"type": "string"},
    "content": {"type": "string"}
  },
  "required": ["path", "content"]
}`),
	}
}

type writeArgs struct {
	Path    string `json:"path"`
	Content string `json:"content"`
}

func (Write) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a writeArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Path == "" {
		return toolErr("path is required")
	}
	path := resolvePath(env, a.Path)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return toolErr(err.Error())
	}
	if err := os.WriteFile(path, []byte(a.Content), 0o644); err != nil {
		return toolErr(err.Error())
	}
	return ok(fmt.Sprintf("wrote %d bytes to %s", len(a.Content), path))
}

// Edit performs an exact-match string replacement in a file. The match must be
// unique unless replace_all is set, so an ambiguous edit fails rather than
// changing the wrong occurrence.
type Edit struct{}

func (Edit) Name() string { return editToolName }

func (Edit) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name:        editToolName,
		Description: "Replace an exact substring in a file. old_string must occur exactly once unless replace_all is true.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "path": {"type": "string"},
    "old_string": {"type": "string"},
    "new_string": {"type": "string"},
    "replace_all": {"type": "boolean"}
  },
  "required": ["path", "old_string", "new_string"]
}`),
	}
}

type editArgs struct {
	Path       string `json:"path"`
	OldString  string `json:"old_string"`
	NewString  string `json:"new_string"`
	ReplaceAll bool   `json:"replace_all"`
}

func (Edit) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a editArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Path == "" || a.OldString == "" {
		return toolErr("path and old_string are required")
	}
	if a.OldString == a.NewString {
		return toolErr("old_string and new_string are identical")
	}
	path := resolvePath(env, a.Path)
	data, err := os.ReadFile(path)
	if err != nil {
		return toolErr(err.Error())
	}
	content := string(data)
	count := strings.Count(content, a.OldString)
	if count == 0 {
		return toolErr("old_string not found")
	}
	if count > 1 && !a.ReplaceAll {
		return toolErr(fmt.Sprintf("old_string occurs %d times; pass replace_all or make it unique", count))
	}
	var updated string
	replaced := 1
	if a.ReplaceAll {
		updated = strings.ReplaceAll(content, a.OldString, a.NewString)
		replaced = count
	} else {
		updated = strings.Replace(content, a.OldString, a.NewString, 1)
	}
	if err := os.WriteFile(path, []byte(updated), 0o644); err != nil {
		return toolErr(err.Error())
	}
	return ok(fmt.Sprintf("replaced %d occurrence(s) in %s", replaced, path))
}

// Package tool holds the small set of capabilities compiled into erg:
// read, write, edit, glob, list, bash, ask, and task. Everything beyond this
// set is an external CLI driven through bash, per the project's extension
// philosophy. Each tool implements agent.Tool.
package tool

import (
	"bytes"
	"encoding/json"
	"fmt"
	"path/filepath"

	"github.com/emergingrobotics/erg/internal/agent"
)

const defaultMaxOutputBytes = 64 * 1024

// Core returns the default always-available toolset. sub may be nil to omit the
// task tool (e.g. inside a sub-run, to prevent unbounded recursion).
func Core(sub SubRunner) agent.Toolset {
	ts := agent.Toolset{
		readToolName:  Read{},
		writeToolName: Write{},
		editToolName:  Edit{},
		globToolName:  Glob{},
		listToolName:  List{},
		bashToolName:  Bash{},
		AskName:       Ask{},
	}
	if sub != nil {
		ts[taskToolName] = Task{Runner: sub}
	}
	return ts
}

// Select returns the subset of the core toolset named in enabled. An unknown
// name is a configuration error. An empty list yields the full core set.
func Select(all agent.Toolset, enabled []string) (agent.Toolset, error) {
	if len(enabled) == 0 {
		return all, nil
	}
	out := make(agent.Toolset, len(enabled))
	for _, name := range enabled {
		if name == SkillName {
			// The skill loader is managed by the wiring layer: it is injected
			// when a shape has lazy skills in an interactive loop, regardless of
			// this list. Listing it here is therefore harmless, not a Core pick.
			continue
		}
		tool, ok := all[name]
		if !ok {
			return nil, fmt.Errorf("unknown tool %q", name)
		}
		out[name] = tool
	}
	return out, nil
}

// decode unmarshals tool arguments, rejecting unknown fields so a malformed
// call fails loudly rather than being silently misinterpreted.
func decode(args json.RawMessage, dst any) error {
	dec := json.NewDecoder(bytes.NewReader(args))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return fmt.Errorf("invalid arguments: %w", err)
	}
	return nil
}

// resolvePath joins a possibly-relative path against the tool environment's
// working directory. Absolute paths are used as-is.
func resolvePath(env agent.ToolEnv, p string) string {
	if p == "" {
		return env.Cwd
	}
	if filepath.IsAbs(p) {
		return filepath.Clean(p)
	}
	return filepath.Join(env.Cwd, p)
}

// capBytes truncates s to n bytes, appending a truncation note when it cuts.
func capBytes(s string, n int) string {
	if n <= 0 || len(s) <= n {
		return s
	}
	return s[:n] + fmt.Sprintf("\n... [truncated %d bytes]", len(s)-n)
}

func ok(content string) (agent.ToolResult, error) {
	return agent.ToolResult{Content: content}, nil
}

func toolErr(content string) (agent.ToolResult, error) {
	return agent.ToolResult{Content: content, IsError: true}, nil
}

package tool

import (
	"context"
	"encoding/json"

	"github.com/emergingrobotics/erg/internal/agent"
)

// AskName is the tool name callers match on to surface a paused question.
const AskName = "ask"

// Ask lets the model pause and request a human decision. It ends the user-turn
// and marks the agent blocked (authoritative, rather than herdr guessing from
// the screen). The human's reply arrives as the next message.
type Ask struct{}

func (Ask) Name() string { return AskName }

func (Ask) Spec() agent.ToolSpec {
	return agent.ToolSpec{
		Name: AskName,
		Description: "Pause and ask the human a question when you need a decision or approval to " +
			"proceed. This ends your turn; the human's reply arrives as the next message. Use it " +
			"instead of guessing on irreversible or ambiguous choices.",
		Schema: json.RawMessage(`{
  "type": "object",
  "properties": {
    "question": {"type": "string", "description": "The question or decision you need from the human."}
  },
  "required": ["question"]
}`),
	}
}

type askArgs struct {
	Question string `json:"question"`
}

func (Ask) Run(_ context.Context, args json.RawMessage, env agent.ToolEnv) (agent.ToolResult, error) {
	var a askArgs
	if err := decode(args, &a); err != nil {
		return agent.ToolResult{}, err
	}
	if a.Question == "" {
		return toolErr("question is required")
	}
	// Running unattended (one-shot, observe reaction, sub-run): no human can
	// answer, so don't park the turn — tell the model to decide and continue.
	if env.Unattended {
		return agent.ToolResult{
			Content: "No human is available to answer (running unattended). Make the safest " +
				"reasonable decision yourself, or stop if you cannot proceed.",
		}, nil
	}
	return agent.ToolResult{
		Content: "Paused for the human. They will answer in the next message; wait for it.",
		EndTurn: true,
	}, nil
}

package agent

import (
	"context"
	"fmt"
	"time"
)

// Deps carries everything the loop needs, resolved and owned before the run
// starts. Nothing here is global mutable state.
type Deps struct {
	Provider   Provider
	Tools      Toolset
	Options    Options
	System     string
	Cwd        string
	MaxTurns   int        // bound on provider round-trips per user-turn (0 = default)
	Limits     ToolLimits // per-tool output/time bounds
	Summarizer Summarizer // optional; enables compaction
	CompactAt  int        // window token estimate that triggers compaction (0 = never)
	Unattended bool       // no human available to answer mid-run (oneshot/observe/sub-runs)
	// LoadedSkills, when set, returns the system-prompt block for skills loaded
	// on demand this session. It is appended to System on every request, so a
	// loaded body lives in the durable system region and survives compaction.
	LoadedSkills func() string
	Clock        func() time.Time
}

// DriverHooks let a frontend supply presentation and cancellation without
// duplicating the continuation loop. All fields are optional.
type DriverHooks struct {
	OnAssistantDelta func(string)
	OnToolCall       func(ToolCall)
	OnToolResult     func(ToolResult)
	OnStatus         func(AgentStatus)
	Cancelled        func() bool
}

// UserInput is one prompt entering a user-turn.
type UserInput struct {
	Text string
}

// Outcome summarizes a completed user-turn.
type Outcome struct {
	Turns   int
	Usage   Usage
	Stopped bool // true if the run hit MaxTurns with tool calls still pending
	Blocked bool // true if a tool ended the turn to wait for a human decision
}

const defaultMaxTurns = 50

// Run executes one user-turn: it appends the user input, then loops
// provider round-trips, dispatching tool calls, until the model stops
// requesting tools, a bound is hit, or the run is cancelled. It mutates log in
// place and returns when the turn settles.
func Run(ctx context.Context, log *Log, dep Deps, in UserInput, hooks DriverHooks) (Outcome, error) {
	clock := dep.Clock
	if clock == nil {
		clock = time.Now
	}
	maxTurns := dep.MaxTurns
	if maxTurns <= 0 {
		maxTurns = defaultMaxTurns
	}

	log.Append(Item{Kind: ItemUserText, Text: in.Text, Meta: ItemMeta{Time: clock()}})
	setStatus(hooks, StatusWorking)

	var out Outcome
	for turnNo := 0; turnNo < maxTurns; turnNo++ {
		if err := checkCancel(ctx, hooks); err != nil {
			setStatus(hooks, StatusIdle)
			return out, err
		}
		if err := maybeCompact(ctx, log, dep); err != nil {
			setStatus(hooks, StatusIdle)
			return out, err
		}

		req := BuildRequest(log, systemPrompt(dep), dep.Tools.Specs())
		ch, err := dep.Provider.Stream(ctx, req, dep.Options)
		if err != nil {
			setStatus(hooks, StatusIdle)
			return out, fmt.Errorf("provider stream: %w", err)
		}

		turn := NewTurn()
		for ev := range ch {
			if ferr := turn.Feed(ev, hooks.OnAssistantDelta); ferr != nil {
				drain(ch)
				setStatus(hooks, StatusIdle)
				return out, ferr
			}
		}

		assistant, calls, usage, err := turn.Result()
		if err != nil {
			setStatus(hooks, StatusIdle)
			return out, fmt.Errorf("turn %d: %w", turnNo, err)
		}
		out.Turns++
		out.Usage.Add(usage)

		if assistant.Kind == ItemAssistantText {
			assistant.Meta = ItemMeta{Time: clock(), Usage: usage}
			log.Append(assistant)
		}

		if len(calls) == 0 {
			setStatus(hooks, StatusIdle)
			return out, nil
		}

		log.Append(Item{Kind: ItemTurnBoundary, Meta: ItemMeta{Time: clock()}})
		for _, call := range calls {
			if err := checkCancel(ctx, hooks); err != nil {
				setStatus(hooks, StatusIdle)
				return out, err
			}
			if dispatch(ctx, log, dep, call, hooks, clock) {
				out.Blocked = true
			}
		}
		if out.Blocked {
			break
		}
	}

	// Reached here either by hitting MaxTurns (Stopped) or by a tool ending the
	// turn to wait for a human (Blocked). Both mean "needs a human."
	if !out.Blocked {
		out.Stopped = true
	}
	setStatus(hooks, StatusBlocked)
	return out, nil
}

// dispatch runs one tool call and appends its call and result items. A tool
// failure is reported back to the model as an error result rather than
// aborting the whole run, which is what lets the model recover. It returns
// whether the tool asked to end the user-turn (ToolResult.EndTurn).
func dispatch(ctx context.Context, log *Log, dep Deps, call ToolCall, hooks DriverHooks, clock func() time.Time) bool {
	c := call
	log.Append(Item{Kind: ItemToolCall, Call: &c, Meta: ItemMeta{Time: clock()}})
	if hooks.OnToolCall != nil {
		hooks.OnToolCall(call)
	}

	res := runTool(ctx, dep, call)

	r := res
	log.Append(Item{Kind: ItemToolResult, Result: &r, Meta: ItemMeta{Time: clock()}})
	if hooks.OnToolResult != nil {
		hooks.OnToolResult(res)
	}
	return res.EndTurn
}

func runTool(ctx context.Context, dep Deps, call ToolCall) ToolResult {
	tool, ok := dep.Tools[call.Name]
	if !ok {
		return ToolResult{CallID: call.ID, Name: call.Name, IsError: true,
			Content: fmt.Sprintf("unknown tool %q", call.Name)}
	}
	env := ToolEnv{Cwd: dep.Cwd, Limits: dep.Limits, Unattended: dep.Unattended}
	res, err := tool.Run(ctx, call.Args, env)
	if err != nil {
		return ToolResult{CallID: call.ID, Name: call.Name, IsError: true, Content: err.Error()}
	}
	res.CallID = call.ID
	res.Name = call.Name
	return res
}

// systemPrompt returns the request's system prompt: the static System plus, when
// skills have been loaded on demand, their bodies. Because these bodies ride in
// the system region rather than the conversation window, compaction cannot drop
// them mid-task.
func systemPrompt(dep Deps) string {
	if dep.LoadedSkills == nil {
		return dep.System
	}
	loaded := dep.LoadedSkills()
	if loaded == "" {
		return dep.System
	}
	if dep.System == "" {
		return loaded
	}
	return dep.System + "\n\n" + loaded
}

func maybeCompact(ctx context.Context, log *Log, dep Deps) error {
	if dep.Summarizer == nil || dep.CompactAt <= 0 {
		return nil
	}
	if EstimateTokens(log.Window()) < dep.CompactAt {
		return nil
	}
	return Compact(ctx, log, dep.Summarizer)
}

func checkCancel(ctx context.Context, hooks DriverHooks) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if hooks.Cancelled != nil && hooks.Cancelled() {
		return context.Canceled
	}
	return nil
}

func setStatus(hooks DriverHooks, s AgentStatus) {
	if hooks.OnStatus != nil {
		hooks.OnStatus(s)
	}
}

func drain(ch <-chan StreamEvent) {
	for range ch {
	}
}
